input.new_string:
import { toggleNotificationPreference, getNotificationPreference } from "./actions";

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <section>
        <h2>Notifications</h2>
        <p>
          Notifications are currently:{" "}
          <strong>{notificationsEnabled ? "On" : "Off"}</strong>
        </p>
        <form action={toggleNotificationPreference}>
          <button type="submit">
            Turn {notificationsEnabled ? "Off" : "On"} Notifications
          </button>
        </form>
      </section>
    </main>
  );
}

